def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5

def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_dedupe_transcripts_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "x", "day": 1, "flagged": True},
        {"id": "y", "day": 2, "flagged": False},
        {"id": "x", "day": 3, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]
